import{_ as o,l as i,o as e,c as l,v as n,p as s,x as t,d as F,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"自由现金流预测","description":"","frontmatter":{"title":"自由现金流预测","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/fcf-forecasting.md","filePath":"econ/fcf-forecasting.md","lastUpdated":1789023840000}'),C={name:"econ/fcf-forecasting.md"};function d(A,a,h,f,_,m){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="自由现金流预测" tabindex="-1">自由现金流预测 <a class="header-anchor" href="#自由现金流预测" aria-label="Permalink to &quot;自由现金流预测&quot;">​</a></h1><div class="epigraph"><p>折现的对象是可以支付给所有资本提供者的现金，不是会计利润；利润可以靠应计做出来，自由现金流必须通过营运资本与再投资。</p><footer>—— 据 Brealey, Myers and Allen, Principles of Corporate Finance；Penman, Financial Statement Analysis and Security Valuation 整理</footer></div><p><a href="/econ/apv">上一课</a>把分母与副作用写清，\\(V_U\\) 仍缺分子：未杠杆自由现金流。本课缺口是预测口径——NOPAT、再投资、营运资本，以及与<a href="/econ/agency-free-cash-flow">Jensen 的 FCF</a> 同名不同用。不重做 WACC 权重，不把终值提前写成增长公式的主体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>会计利润扣了利息、折旧政策与应计，不能直接进 NPV。对全部资本提供者的自由现金流（FCFF）标准写法是：税后净经营利润（按无杠杆税）加回非现金费用，减资本支出与营运资本增量。漏掉营运资本：高速成长的报表利润好看，现金被应收和存货锁住，NPV 被高估。缺口不是「会不会做 Excel」，而是：资本预算的分子必须与分母的 \\(r_U\\) 或 WACC 匹配，且增量——只记项目引起的现金流，沉没与已分摊的总部费用不进。</p><p>Jensen 的自由现金流是筛子已空后可被浪费的现金；估值的 FCFF 是项目或企业能产生的、尚未决定派不派的现金。同名：一个是代理对象，一个是折现对象。预测时不要用「尽量把 FCF 做成正」来回避再投资；再投资是正 NPV 的代价。</p><p><span class="marginnote">无杠杆税：用 \\(EBIT\\times(1-\\tau_c)\\)，即使企业实际付息。利息税盾不在 FCFF 里扣，留给 WACC 或 APV。股权自由现金流（FCFE）才扣税后利息与净借债。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>增量原则。比较「做项目」与「不做」：额外的收入、成本、税、垫付的营运资本、期末收回。已有土地的机会成本按市价进流出，账面沉没不进。通货膨胀：名义现金流配名义 \\(r\\)，下一课专讲；本课只禁止混用。</p><p>预测要有资产负债表约束：净经营资产增长 = 再投资；FCFF = NOPAT − 净经营资产增量（在干净盈余、无非经营项时）。Penman 把这写成剩余收益与现金流的桥梁，后课 EVA 再用。没有这层约束，收入增长与资本支出可以互相打架，终值会爆炸。</p>',10)),(e(),s(p,null,{default:t(()=>[c(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EBIT%5B%22EBIT%22%5D%20--%3E%20NOPAT%5B%22NOPAT%20%3D%20EBIT%20x%20(1-Tc)%22%5D%0A%20%20NOPAT%20--%3E%20FCFF%5B%22FCFF%22%5D%0A%20%20CAPEX%5B%22%E8%B5%84%E6%9C%AC%E6%94%AF%E5%87%BA%22%5D%20--%3E%20FCFF%0A%20%20WC%5B%22%E8%90%A5%E8%BF%90%E8%B5%84%E6%9C%AC%E5%A2%9E%E9%87%8F%22%5D%20--%3E%20FCFF%0A%20%20FCFF%20--%3E%20VU%5B%22%E7%94%A8%20rU%20%E6%88%96%20WACC%20%E6%8A%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[F(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>情景，不是单一的「管理当局计划」。上行不要偷偷提高利润率又降低再投资；竞争会吃掉超额利润，后课终值会把这一点写成竞争均衡 ROIC。本课先要求：利润率、周转、再投资三件套内部一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是权责发生制与现金间隔。收入可以在货没收回时确认；NPV 只认现金。营运资本是间隔的存量。折旧影响税，从而影响现金，但折旧本身不是现金——所以加回。资本预算若用「EBITDA 倍数」当现金流，等于忽略税与再投资，只在后课乘数里作为粗糙可比，不能替代本课的分子。</p><p>与优序、代理的衔接：预测里「管理当局不愿吐出现金」会表现为过度再投资（负 NPV 的 capex）。估值应把再投资拆成维持性与增长性，增长性部分用增量 ROIC 对 WACC 判断是否创造价值，而不是把所有 capex 都当好。这是 Jensen 筛子在预测表上的落地，不是再写一遍债务纪律。</p><h3 id="总部费用与协同" tabindex="-1">总部费用与协同 <a class="header-anchor" href="#总部费用与协同" aria-label="Permalink to &quot;总部费用与协同&quot;">​</a></h3><p>分摊到项目的固定总部费用，若项目不改变总部现金，不进增量 FCFF。协同若改变其他部门现金，要进增量，并防止在并购课里再加一遍。Tirole：可验证的现金比不可验证的「战略」优先进入合同；估值同样。</p><p><span class="marginnote">干净盈余：本期账面增值来自盈余而非直接进权益的调整。脏项（某些公允价值、外币）会让 NOPAT 与 FCFF 对不上。预测用经营口径，把金融资产负债分开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成会计课的完整调整清单。对象是口径与增量。也不要把 FCFF 预测当成已经解决了终值：显式期之后的增长与再投资是下一课。宏观课序里的总量消费不是企业 FCFF；不要把 DSGE 的校准参数直接塞进一家公司的利润率。</p><p>后课默认：显式期 FCFF 与 NOPAT、净经营资产一致；税盾不在 FCFF 里重复；增量、机会成本、沉没已分开。下一课：显式期之后的价值往往占 DCF 的大部分。</p><p>Jensen 的 FCF 与估值 FCFF 同名：筛子空时的浪费对估值是负的再投资或低 ROIC，不是另加一项「代理折现率」了事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FCFF = 无杠杆税后经营利润 − 净经营资产增量；与 WACC/APV 口径匹配。</li><li>增量、机会成本、营运资本缺一则 NPV 歪；会计利润不是折现对象。</li><li>估值 FCF 与 Jensen 的 FCF 同名不同用：一个是分子，一个是代理弹药。</li><li>出处：Brealey, Myers and Allen；Penman, <em>Financial Statement Analysis</em>。</li></ul>',13))])}const T=o(C,[["render",d]]);export{E as __pageData,T as default};
